use pob_calc::modules::calc_tools as calcLib;
use pob_calc::modules::calc_triggers::handlers::{
    defaultComparer, defaultTriggerHandler, helmetFocusHandler, isTriggered, slotMatch, CWCHandler,
    ComparerFn, SkillCondFn,
};
use pob_calc::modules::calc_triggers::TriggerConfig;
use pob_calc::modules::common::cacheSkillUUID;
use pob_calc::prelude::*;
use pob_oracle::headless::{Engine, Ret};
use pob_oracle::jit::JitPob;
use pob_oracle::oracle::{find_parity_dir, find_pob_src};
use pob_oracle::schema::{HitsIndex, StateDump};
use pob_oracle::testkit;

fn skip(why: &str) {
    let required = std::env::var_os("POB_ORACLE_REQUIRE").is_some_and(|v| v == "1")
        || std::env::var_os("CI").is_some_and(|v| !v.is_empty() && v != "false" && v != "0");
    assert!(!required, "required input missing: {why}");
    eprintln!("SKIPPED: {why}");
}

fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("corpus/TR-A")
}

fn stem(p: &Path) -> &str {
    p.file_stem().and_then(|s| s.to_str()).unwrap_or_default()
}

// ---- corpus generation ----------------------------------------------------------------------------

/// The `it("<name>", function() … end)` cases of the spec, and the describe-level helper
/// functions they call (everything before `before_each`).
fn spec_cases(spec: &str) -> (String, Vec<(String, String)>) {
    let lines: Vec<&str> = spec.lines().collect();
    let start = lines
        .iter()
        .position(|l| l.starts_with("describe("))
        .map_or(0, |i| i + 1);
    let helpers_end = lines
        .iter()
        .position(|l| l.trim_start().starts_with("before_each("))
        .unwrap_or(start);
    let helpers = lines[start..helpers_end].join("\n");
    let mut cases = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let l = lines[i];
        if let Some(rest) = l.strip_prefix("\tit(\"") {
            let name = rest.split('"').next().unwrap_or_default().to_owned();
            let mut body = Vec::new();
            i += 1;
            while i < lines.len() && lines[i] != "\tend)" {
                // the assertions are not part of the build
                if !lines[i].trim_start().starts_with("assert") {
                    body.push(lines[i]);
                }
                i += 1;
            }
            cases.push((name, body.join("\n")));
        }
        i += 1;
    }
    (helpers, cases)
}

fn slug(name: &str) -> String {
    let mut s: String = name
        .to_ascii_lowercase()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
        .collect();
    while s.contains("__") {
        s = s.replace("__", "_");
    }
    format!("tra_{}", s.trim_matches('_'))
}

/// Regenerate `corpus/TR-A/*.xml` from PoB's trigger spec (run by hand:
/// `scripts/port/cargo.sh test -p pob-oracle --test TR-A -- --ignored tra_generate_corpus`).
#[test]
#[ignore = "regenerates the committed corpus"]
fn tra_generate_corpus() {
    let Some(src) = find_pob_src() else {
        return skip("no PoB checkout");
    };
    let spec_path = src.join("../spec/System/TestTriggers_spec.lua");
    let Ok(spec) = std::fs::read_to_string(&spec_path) else {
        return skip("no spec/System/TestTriggers_spec.lua");
    };
    let (helpers, cases) = spec_cases(&spec);
    let _lock = pob_oracle::runner::OracleLock::acquire().unwrap_or_else(|e| panic!("{e}"));
    let mut pob = JitPob::boot_oracle(&src, None).unwrap_or_else(|e| panic!("boot: {e}"));
    let dir = corpus_dir();
    std::fs::create_dir_all(&dir).unwrap();
    let mut ok = 0;
    for (name, body) in &cases {
        let code = format!(
            "function newBuild()\n\
             __mainObject__.main:SetMode(\"BUILD\", false, \"Help, I'm stuck in Path of Building!\")\n\
             runCallback(\"OnFrame\")\n\
             build = __mainObject__.main.modes[\"BUILD\"]\n\
             end\n\
             local ok, err = pcall(function()\n\
             newBuild()\n\
             {helpers}\n\
             {body}\n\
             end)\n\
             if not ok then return \"ERR:\" .. tostring(err) end\n\
             return build:SaveDB(\"tr_a\")"
        );
        match pob.run(&code) {
            Ok(r) => match r.first() {
                Some(Ret::Str(xml)) if !xml.starts_with("ERR:") => {
                    std::fs::write(dir.join(format!("{}.xml", slug(name))), xml).unwrap();
                    ok += 1;
                }
                other => eprintln!("{name}: {other:?}"),
            },
            Err(e) => eprintln!("{name}: {e}"),
        }
    }
    eprintln!("{ok}/{} spec cases saved to {}", cases.len(), dir.display());
    assert!(ok > 0);
}

// ---- scaffold dispatcher (TR-B's CalcTriggers.lua 902-1627; replaced when TR-B lands) -----------

fn has(skill: &ActiveSkillRef, t: SkillType::T) -> bool {
    skill.skillTypes.get().with(|s| s.has(t))
}

fn flags(skill: &ActiveSkillRef) -> u32 {
    skill.skillCfg.get().flags.get()
}

fn pmain(env: &EnvRef) -> ActiveSkillRef {
    env.player.mainSkill.get().expect("env.player.mainSkill")
}

fn cond(f: impl Fn(&EnvRef, &ActiveSkillRef) -> bool + 'static) -> Option<SkillCondFn> {
    Some(Rc::new(f))
}

fn named(n: &str) -> Option<Name> {
    Some(Name::from(n))
}

/// The configTable keys (CalcTriggers.lua 902-1584), from the Lua source.
fn config_keys(src: &Path) -> Vec<String> {
    let lua = std::fs::read_to_string(src.join("Modules/CalcTriggers.lua")).unwrap_or_default();
    let mut keys = Vec::new();
    let mut inside = false;
    for l in lua.lines() {
        if l.starts_with("local configTable = {") {
            inside = true;
            continue;
        }
        if inside && l == "}" {
            break;
        }
        if inside {
            if let Some(rest) = l.strip_prefix("\t[\"") {
                if let Some(k) = rest.split("\"]").next() {
                    keys.push(k.to_owned());
                }
            }
        }
    }
    keys
}

/// `configTable[key](env)` for the arms the scaffold carries (transcribed from CalcTriggers.lua);
/// `None` = an arm the scaffold does not carry.
fn arm(key: &str, env: &EnvRef) -> Option<Option<TriggerConfig>> {
    let melee_or_attack = || cond(|_, s| has(s, SkillType::Melee) || has(s, SkillType::Attack));
    let damage_or_attack = || cond(|_, s| has(s, SkillType::Damage) || has(s, SkillType::Attack));
    let c = TriggerConfig::default;
    let named_cfg = |name: &str, f: Option<SkillCondFn>| {
        Some(TriggerConfig {
            triggerName: named(name),
            triggerSkillCond: f,
            ..c()
        })
    };
    let kills = |f: Option<SkillCondFn>| {
        Some(TriggerConfig {
            assumingEveryHitKills: true,
            triggerSkillCond: f,
            ..c()
        })
    };
    let with_triggered = |trig: Option<SkillCondFn>, triggered: SkillCondFn| {
        let mut t = TriggerConfig {
            triggerSkillCond: trig,
            ..c()
        };
        t.triggeredSkillCond = Some(triggered);
        Some(t)
    };
    let self_source = || {
        pmain(env).skillFlags.get().set(n!("globalTrigger"), true);
        Some(TriggerConfig {
            source: Some(pmain(env)),
            ..c()
        })
    };
    let player_db = env.player.modDB.get();
    Some(match key {
        // 903
        "law of the wilds" => Some(TriggerConfig {
            triggerSkillCond: cond(|_, s| {
                !has(s, SkillType::SummonsTotem)
                    && (has(s, SkillType::Melee) || has(s, SkillType::Attack))
                    && flags(s) & ModFlag::Claw > 0
            }),
            ..c()
        }),
        // 910 / 919
        "the rippling thoughts" | "the surging thoughts" => {
            if ge_name(&pmain(env)) == "Storm Cascade" {
                Some(TriggerConfig {
                    triggerOnUse: key == "the surging thoughts",
                    triggerSkillCond: melee_or_attack(),
                    ..c()
                })
            } else {
                None
            }
        }
        // 944-951
        "replica eternity shroud" | "shroud of the lightless" | "tempest shield" => self_source(),
        // 952-990
        "limbsplit" | "the cauteriser" => named_cfg("Gore Shockwave", melee_or_attack()),
        "duskblight" => named_cfg("Stalking Pustule", damage_or_attack()),
        "lioneye's paws" | "replica lioneye's paws" => {
            pmain(env).skillData.get().set(n!("cooldown"), 1.0);
            Some(TriggerConfig {
                triggerOnUse: true,
                triggerSkillCond: cond(|_, s| {
                    has(s, SkillType::Attack) && flags(s) & ModFlag::Bow > 0
                }),
                ..c()
            })
        }
        "moonbender's wing" => {
            pmain(env).skillData.get().set(n!("cooldown"), 1.0);
            named_cfg("Lightning Warp", melee_or_attack())
        }
        "ngamahu's flame" => named_cfg("Molten Burst", melee_or_attack()),
        "cameria's avarice" => named_cfg("Icicle Burst", damage_or_attack()),
        "starcaller" => named_cfg("Starfall", melee_or_attack()),
        "uul-netol's embrace" => named_cfg("Bone Nova", damage_or_attack()),
        // 990-1001
        "rigwald's crest" | "jorrhast's blacksteel" | "ashcaller" => {
            pmain(env)
                .skillData
                .get()
                .set(n!("sourceRateIsFinal"), true);
            kills(damage_or_attack())
        }
        // 1002-1013
        "arakaali's fang" | "sporeguard" | "mark of the elder" | "mark of the shaper" => {
            kills(damage_or_attack())
        }
        // 1088
        "kitava's thirst" => {
            let requiredManaCost =
                player_db.Sum(ModType::BASE, None, &[n!("KitavaRequiredManaCost")]);
            let mut t = TriggerConfig {
                triggerChance: Some(player_db.Sum(
                    ModType::BASE,
                    None,
                    &[n!("KitavaTriggerChance")],
                )),
                triggerName: named("Kitava's Thirst"),
                triggerSkillCond: cond(|_, _| true),
                ..c()
            };
            let cmp: ComparerFn = Rc::new(move |env, uuid, source, triggerRate| {
                let e = cachedData(env.mode, uuid).expect("cache entry");
                let cachedSpeed = lor(e.HitSpeed.clone(), || e.Speed.clone());
                let cachedManaCost = e.ManaCost.clone();
                ((source.is_none() && cachedSpeed.truthy())
                    || (cachedSpeed.truthy() && cachedSpeed.num() > triggerRate.unwrap_or(0.0)))
                    && cachedManaCost.num_or(0.0) >= requiredManaCost
            });
            t.comparer = Some(cmp);
            Some(t)
        }
        // 1114-1135
        "mjolner" => with_triggered(
            cond(|env, s| {
                (has(s, SkillType::Damage) || has(s, SkillType::Attack))
                    && flags(s) & (ModFlag::Mace | ModFlag::Weapon1H) > 0
                    && !slotMatch(env, s)
            }),
            Rc::new(|env, s| {
                s.skillData.get().truthy(n!("triggeredByMjolner")) && slotMatch(env, s)
            }),
        ),
        "wing of the wyvern" => with_triggered(
            cond(|env, s| {
                (has(s, SkillType::Damage) || has(s, SkillType::Attack))
                    && flags(s) & ModFlag::Bow > 0
                    && !slotMatch(env, s)
            }),
            Rc::new(|env, s| {
                s.skillData.get().truthy(n!("triggeredByUnique")) && slotMatch(env, s)
            }),
        ),
        "cospri's malice" => with_triggered(
            cond(|_, s| {
                has(s, SkillType::Melee) && flags(s) & (ModFlag::Sword | ModFlag::Weapon1H) > 0
            }),
            Rc::new(|env, s| {
                s.skillData.get().truthy(n!("triggeredByCospris"))
                    && pmain(env)
                        .socketGroup
                        .get()
                        .expect("socketGroup")
                        .slot
                        .get()
                        == s.socketGroup.get().expect("socketGroup").slot.get()
            }),
        ),
        "kinetic flux" => with_triggered(
            cond(|env, s| has(s, SkillType::Attack) && slotMatch(env, s)),
            Rc::new(|env, s| {
                s.skillData.get().truthy(n!("triggeredByKineticFlux")) && slotMatch(env, s)
            }),
        ),
        // 1156
        "cast on critical strike" => with_triggered(
            cond(|env, s| has(s, SkillType::Attack) && slotMatch(env, s)),
            Rc::new(|env, s| s.skillData.get().truthy(n!("triggeredByCoc")) && slotMatch(env, s)),
        ),
        // 1160
        "cast on melee kill" => {
            if player_db.Flag(None, &[n!("Condition:KilledRecently")]) {
                let mut t = with_triggered(
                    cond(|env, s| {
                        has(s, SkillType::Attack) && has(s, SkillType::Melee) && slotMatch(env, s)
                    }),
                    Rc::new(|env, s| {
                        s.skillData.get().truthy(n!("triggeredByMeleeKill")) && slotMatch(env, s)
                    }),
                )
                .unwrap();
                t.assumingEveryHitKills = true;
                Some(t)
            } else {
                let m = pmain(env);
                m.infoMessage2
                    .set(Some(LStr::from("DPS reported assuming Self-Cast")));
                m.infoMessage
                    .set(Some(LStr::from("Cast on Melee Kill requires recent kills")));
                None
            }
        }
        // 1180
        "cast when damage taken" => {
            let m = pmain(env);
            let sd = m.skillData.get();
            if sd.truthy(n!("triggeredByDamageTaken")) {
                let thresholdMod =
                    calcLib::r#mod(&m.skillModList.get(), None, &[n!("CWDTThreshold")]);
                let out = env.player.output.get();
                out.set(
                    n!("CWDTThreshold"),
                    sd.get(n!("triggeredByDamageTaken")).num() * thresholdMod,
                );
                if let Some(bd) = env.player.breakdown.get() {
                    if !out
                        .get(n!("CWDTThreshold"))
                        .raw_eq(&sd.get(n!("triggeredByDamageTaken")))
                    {
                        bd.t.set(
                            n!("CWDTThreshold"),
                            tbl![
                                lfmt!(
                                    "%.2f ^8(base threshold)",
                                    sd.get(n!("triggeredByDamageTaken")).num()
                                ),
                                lfmt!("x %.2f ^8(threshold modifier)", thresholdMod),
                                lfmt!("= %.2f", out.get(n!("CWDTThreshold")).num()),
                            ],
                        );
                    }
                }
                m.skillFlags.get().set(n!("globalTrigger"), true);
                Some(TriggerConfig {
                    source: Some(m.clone()),
                    ..c()
                })
            } else {
                None
            }
        }
        // 1195
        "cast when stunned" => {
            let m = pmain(env);
            m.skillFlags.get().set(n!("globalTrigger"), true);
            Some(TriggerConfig {
                triggerChance: m.skillData.get().get(n!("chanceToTriggerOnStun")).opt_num(),
                source: Some(m.clone()),
                ..c()
            })
        }
        // 1280-1290
        "mark on hit" => Some(TriggerConfig {
            triggerSkillCond: cond(|_, s| has(s, SkillType::Attack)),
            ..c()
        }),
        "hextouch" => {
            pmain(env)
                .skillData
                .get()
                .set(n!("sourceRateIsFinal"), true);
            Some(TriggerConfig {
                triggerSkillCond: cond(|env, s| has(s, SkillType::Attack) && slotMatch(env, s)),
                ..c()
            })
        }
        "oskarm" => {
            pmain(env)
                .skillData
                .get()
                .set(n!("sourceRateIsFinal"), true);
            Some(TriggerConfig {
                triggerSkillCond: cond(|_, s| has(s, SkillType::Attack)),
                ..c()
            })
        }
        // 1326
        "arcanist brand" => {
            let m = pmain(env);
            if ge_name(&m) != "Arcanist Brand" {
                m.skillData.get().set(n!("sourceRateIsFinal"), true);
                let tb = m.triggeredBy.get().expect("triggeredBy");
                for s in env.player.activeSkillList.get().with(|l| l.clone()) {
                    if ge_name(&s) == "Arcanist Brand" {
                        tb.extra.set(
                            n!("mainSkill"),
                            Val::Obj(s.clone() as Rc<dyn std::any::Any>),
                        );
                        break;
                    }
                }
                let brand = tb
                    .extra
                    .obj::<pob_calc::active_skill::ActiveSkill>(n!("mainSkill"))
                    .expect("triggeredBy.mainSkill");
                let bml = brand.skillModList.get();
                let bcfg = brand.skillCfg.get();
                let activationFreqInc = (100.0
                    + bml.Sum(
                        ModType::INC,
                        Some(&bcfg),
                        &[n!("Speed"), n!("BrandActivationFrequency")],
                    ))
                    / 100.0;
                let activationFreqMore = bml.More(Some(&bcfg), &[n!("BrandActivationFrequency")]);
                tb.extra.set(n!("activationFreqInc"), activationFreqInc);
                tb.extra.set(n!("activationFreqMore"), activationFreqMore);
                tb.extra.set(
                    n!("attachedBrandCount"),
                    brand.skillData.get().get(n!("attachedBrandCount")),
                );
                tb.extra.set(n!("ignoresTickRate"), true);
                let mut t = TriggerConfig {
                    source: Some(brand.clone()),
                    ..c()
                };
                t.extra.set(
                    n!("trigRate"),
                    brand.skillData.get().get(n!("repeatFrequency")).num()
                        * activationFreqInc
                        * activationFreqMore
                        * tb.extra.get(n!("attachedBrandCount")).num(),
                );
                t.triggeredSkillCond = Some(Rc::new(|env, s| {
                    s.skillData.get().truthy(n!("triggeredByBrand")) && slotMatch(env, s)
                }));
                Some(t)
            } else {
                None
            }
        }
        // 1352
        "combust" => {
            let mut t = TriggerConfig {
                triggerSkillCond: cond(|_, s| has(s, SkillType::Melee)),
                ..c()
            };
            t.comparer = Some(Rc::new(|env, uuid, source, triggerRate| {
                let uptimeRatio = cachedData(env.mode, uuid)
                    .expect("cache entry")
                    .Env
                    .player
                    .output
                    .get()
                    .get(n!("InfernalUpTimeRatio"));
                defaultComparer(env, uuid, source, triggerRate) && uptimeRatio.truthy()
            }));
            Some(t)
        }
        // 1360-1376
        "prismatic burst" => Some(TriggerConfig {
            triggerSkillCond: cond(|env, s| has(s, SkillType::Attack) && slotMatch(env, s)),
            ..c()
        }),
        "shockwave" | "void shockwave" | "falling crystal" => Some(TriggerConfig {
            triggerSkillCond: cond(|env, s| has(s, SkillType::Melee) && slotMatch(env, s)),
            ..c()
        }),
        // 1383
        "manaforged arrows" => Some(TriggerConfig {
            triggerOnUse: true,
            triggerName: named("Manaforged Arrows"),
            triggerSkillCond: cond(|_, s| has(s, SkillType::Attack) && flags(s) & ModFlag::Bow > 0),
            ..c()
        }),
        // 1388
        "doom blast" => {
            if env
                .build
                .configTab
                .input
                .get(n!("doomBlastSource"))
                .str()
                .as_deref()
                == Some("replacement")
            {
                player_db.NewMod(
                    n!("UsesCurseOverlaps"),
                    ModType::FLAG,
                    true,
                    "Config",
                    0,
                    0,
                    &[],
                );
            }
            pmain(env).skillData.get().set(n!("ignoresTickRate"), true);
            let overlaps = if !player_db
                .Tabulate(Some(ModType::BASE), None, &[n!("Multiplier:CurseOverlaps")])
                .is_empty()
            {
                Val::Num(m_max(
                    player_db.Sum(ModType::BASE, None, &[n!("Multiplier:CurseOverlaps")]),
                    1.0,
                ))
            } else {
                Val::Bool(false)
            };
            let t = TriggerConfig {
                useCastRate: true,
                triggerSkillCond: cond(|env, s| has(s, SkillType::Hex) && slotMatch(env, s)),
                ..c()
            };
            t.extra.set(n!("overlaps"), overlaps);
            t.extra
                .set(n!("customTriggerName"), "Doom Blast triggering Hex: ");
            Some(t)
        }
        // 1398 / 1401
        "cast while channelling" => Some(TriggerConfig {
            customHandler: Some(CWCHandler),
            ..c()
        }),
        "focus" => Some(TriggerConfig {
            customHandler: Some(helmetFocusHandler),
            ..c()
        }),
        // 1535 / 1544
        "ghostly artillery" => {
            let t = TriggerConfig {
                triggerOnUse: true,
                triggerSkillCond: cond(|_, s| has(s, SkillType::Attack)),
                sourceWeapon: true,
                ..c()
            };
            Some(t)
        }
        "replica gifts from above" => Some(TriggerConfig {
            triggerSkillCond: cond(|_, s| {
                !has(s, SkillType::SummonsTotem) && has(s, SkillType::Attack)
            }),
            ..c()
        }),
        // 928
        "the hidden blade" => {
            let m = pmain(env);
            m.skillFlags.get().set(n!("globalTrigger"), true);
            m.skillData.get().set(n!("triggerRateCapOverride"), 2.0);
            if player_db.Flag(None, &[n!("Condition:Phasing")]) {
                if let Some(bd) = env.player.breakdown.get() {
                    let o = m.skillData.get().get(n!("triggerRateCapOverride")).num();
                    bd.t.set(
                        n!("TriggerRateCap"),
                        tbl![
                            lfmt!("%.2f ^8(Unseen Strike from The Hidden Blade has no cooldown but is still triggered)", o),
                            lfmt!("= %.2f", o),
                        ],
                    );
                }
                Some(TriggerConfig {
                    source: Some(m.clone()),
                    ..c()
                })
            } else {
                m.skillFlags.get().set(n!("disable"), true);
                m.disableReason
                    .set(Some(LStr::from("This skill is requires you to be phasing")));
                None
            }
        }
        // 1014 / 1036
        "poet's pen" | "asenath's chant" => {
            let wand = key == "poet's pen";
            with_triggered(
                cond(move |_, s| {
                    (has(s, SkillType::Damage) || has(s, SkillType::Attack))
                        && flags(s) & (if wand { ModFlag::Wand } else { ModFlag::Bow }) > 0
                }),
                Rc::new(|env, s| {
                    s.skillData.get().truthy(n!("triggeredByUnique"))
                        && pmain(env)
                            .socketGroup
                            .get()
                            .expect("socketGroup")
                            .slot
                            .get()
                            == s.socketGroup.get().expect("socketGroup").slot.get()
                        && has(s, SkillType::Spell)
                }),
            )
            .map(|mut t| {
                t.triggerOnUse = true;
                t
            })
        }
        // 1045
        "vixen's entrapment" => Some(TriggerConfig {
            useCastRate: true,
            triggerSkillCond: cond(|_, s| has(s, SkillType::Hex)),
            ..c()
        }),
        // 1060
        "trigger craft" => {
            let m = pmain(env);
            if m.skillData.get().truthy(n!("triggeredByCraft")) {
                let (mut trigRate, mut source, mut uuid, mut useCastRate) =
                    (None::<f64>, None::<ActiveSkillRef>, None::<Name>, false);
                let triggeredSkills = Table::new();
                for s in env.player.activeSkillList.get().with(|l| l.clone()) {
                    if (has(&s, SkillType::Damage)
                        || has(&s, SkillType::Attack)
                        || has(&s, SkillType::Spell))
                        && !s.skillFlags.get().truthy(n!("aura"))
                        && !Rc::ptr_eq(&s, &m)
                        && !s.skillData.get().truthy(n!("triggeredByCraft"))
                        && !pob_calc::modules::calc_setup::init_env_skills::grantedEffect_fromItem(
                            &s.activeEffect.get().grantedEffect.get(),
                        )
                        && !isTriggered(&s)
                    {
                        let r = pob_calc::modules::calc_triggers::handlers::findTriggerSkill(
                            env,
                            &s,
                            source.take(),
                            trigRate,
                            None,
                        );
                        source = r.0;
                        trigRate = r.1;
                        uuid = r.2;
                        let sf = s.skillFlags.get();
                        let ge = s.activeEffect.get().grantedEffect.get();
                        if (sf.truthy(n!("totem"))
                            || sf.truthy(n!("golem"))
                            || sf.truthy(n!("banner"))
                            || sf.truthy(n!("ballista")))
                            && ge.castTime.is_some()
                        {
                            let cd = ge
                                .levels
                                .get(s.activeEffect.get().level.get())
                                .and_then(|l| l.num(n!("cooldown")))
                                .unwrap_or(0.0);
                            trigRate = Some(1.0 / (ge.castTime.unwrap() + cd));
                            useCastRate = true;
                        }
                    }
                    if s.skillData.get().truthy(n!("triggeredByCraft"))
                        && m.socketGroup.get().expect("socketGroup").slot.get()
                            == s.socketGroup.get().expect("socketGroup").slot.get()
                    {
                        triggeredSkills.push(
                            pob_calc::modules::calc_triggers::handlers::packageSkillDataForSimulation(&s, env),
                        );
                    }
                }
                let t = TriggerConfig {
                    source,
                    useCastRate,
                    ..c()
                };
                t.extra.set(n!("trigRate"), trigRate);
                t.extra.set(n!("uuid"), uuid.map_or(Val::Nil, Val::from));
                t.extra.set(n!("triggeredSkills"), triggeredSkills);
                Some(t)
            } else {
                None
            }
        }
        // 1172
        "nova" => match env.minion.get() {
            Some(minion) if minion.mainSkill.get().is_some() => {
                let ms = minion.mainSkill.get().unwrap();
                let t = TriggerConfig {
                    triggerName: named("Summon Holy Relic"),
                    actor: Some(minion.clone()),
                    triggerSkillCond: cond(|_, s| has(s, SkillType::Attack)),
                    ..c()
                };
                t.extra.set(
                    n!("triggeredSkills"),
                    tbl![tbl! {
                        uuid = cacheSkillUUID(&ms, env),
                        cd = ms.skillData.get().get(n!("cooldown")),
                    }],
                );
                Some(t)
            }
            _ => None,
        },
        // 1205
        "spellslinger" => {
            let m = pmain(env);
            if ge_name(&m) == "Spellslinger" {
                m.skillFlags.get().set(n!("skipEffectiveRate"), true);
            }
            m.skillData.get().set(n!("sourceRateIsFinal"), true);
            Some(TriggerConfig {
                triggerName: named("Spellslinger"),
                triggerOnUse: true,
                triggerSkillCond: cond(|_, s| {
                    has(s, SkillType::Attack)
                        && has(s, SkillType::Projectile)
                        && flags(s) & ModFlag::Wand > 0
                        && !s.skillData.get().truthy(n!("triggeredBySpellSlinger"))
                }),
                ..c()
            })
        }
        // 1236
        "automation" => {
            let m = pmain(env);
            if ge_name(&m) == "Automation" {
                m.skillFlags.get().set(n!("globalTrigger"), true);
                m.skillFlags.get().set(n!("skipEffectiveRate"), true);
            } else {
                for s in env.player.activeSkillList.get().with(|l| l.clone()) {
                    if ge_name(&s) == "Automation" {
                        m.triggeredBy
                            .get()
                            .expect("triggeredBy")
                            .grantedEffect
                            .set(s.activeEffect.get().grantedEffect.get());
                        break;
                    }
                }
            }
            Some(TriggerConfig {
                triggerOnUse: true,
                useCastRate: true,
                source: Some(m.clone()),
                ..c()
            })
        }
        _ => return None,
    })
}

fn ge_name(s: &ActiveSkillRef) -> Name {
    s.activeEffect.get().grantedEffect.get().name
}

/// CalcTriggers.lua:1585-1600 (TR-B) for the scaffold.
fn getUniqueItemTriggerName(skill: &ActiveSkillRef) -> Option<String> {
    let ts = skill.skillData.get().get(n!("triggerSource"));
    if ts.truthy() {
        return ts.str().map(|s| s.to_string());
    }
    let supports = skill.supportList.get().with(|l| l.clone());
    if !supports.is_empty() {
        for gemInstance in supports {
            let ge = gemInstance.grantedEffect.get();
            if pob_calc::modules::calc_setup::init_env_skills::grantedEffect_fromItem(&ge)
                && !ge.support
            {
                return Some(ge.name.to_string());
            }
        }
    }
    let src = skill.socketGroup.get().and_then(|g| g.source.get())?;
    pob_lua::lmatch(&src, ".*:.*:(.*),.*", None).map(|c| c[0].as_str().to_owned())
}

/// What the scaffold `calcs.triggers` did with one hit.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
enum Disp {
    /// `actor` nil, the main skill disabled or limited: nothing runs.
    Skipped,
    /// No configTable arm for any key: `skillData.triggered = nil`.
    NoConfig,
    /// The key has an arm the scaffold does not carry.
    Untested(String),
    /// The handler ran (`default`, `CWC`, `Focus`; `arm-nil` = the arm returned nil).
    Ran(String, &'static str),
}

/// CalcTriggers.lua:1602-1627 (TR-B) for the scaffold.
fn scaffold_triggers(env: &EnvRef, actor: Option<&ActorRef>, keys: &[String]) -> Disp {
    let Some(actor) = actor else {
        return Disp::Skipped;
    };
    let mainSkill = actor.mainSkill.get().expect("actor.mainSkill");
    let limited = env
        .limitedSkills
        .get()
        .is_some_and(|t| t.truthy(cacheSkillUUID(&mainSkill, env)));
    if mainSkill.skillFlags.get().truthy(n!("disable")) || limited {
        return Disp::Skipped;
    }
    let ge = mainSkill.activeEffect.get().grantedEffect.get();
    let skillName = ge.name;
    let triggerName = mainSkill
        .triggeredBy
        .get()
        .map(|tb| tb.grantedEffect.get().name);
    let uniqueName = if isTriggered(&mainSkill) {
        getUniqueItemTriggerName(&mainSkill)
    } else {
        None
    };
    let triggerNameLower = triggerName.map(|t| t.as_str().to_ascii_lowercase());
    let awakened = triggerNameLower
        .as_ref()
        .map(|t| t.strip_prefix("awakened ").unwrap_or(t).to_owned());
    let candidates = [
        Some(ge.id.as_str().to_owned()),
        Some(skillName.as_str().to_ascii_lowercase()),
        triggerNameLower,
        awakened,
        uniqueName.as_ref().map(|u| u.to_ascii_lowercase()),
    ];
    let mut config = None;
    let mut used = String::new();
    for key in candidates.into_iter().flatten() {
        if !keys.contains(&key) {
            continue;
        }
        match arm(&key, env) {
            None => return Disp::Untested(key),
            Some(c) => {
                used = key;
                config = c;
            }
        }
        if config.is_some() {
            break;
        }
    }
    if let Some(mut config) = config {
        config.actor = config.actor.or_else(|| Some(actor.clone()));
        config.triggerName = config
            .triggerName
            .or(triggerName)
            .or(Some(skillName))
            .or_else(|| uniqueName.as_deref().map(Name::from));
        config.triggerChance = config.triggerChance.or_else(|| {
            mainSkill
                .activeEffect
                .get()
                .srcInstance
                .get()
                .and_then(|g| g.extra.get(n!("triggerChance")).opt_num())
        });
        let which = match config.customHandler {
            Some(h)
                if h as usize
                    == (CWCHandler as fn(&EnvRef, &mut TriggerConfig) -> Option<Table>)
                        as usize =>
            {
                "CWC"
            }
            Some(_) => "Focus",
            None => "default",
        };
        let handler = config.customHandler.unwrap_or(defaultTriggerHandler);
        handler(env, &mut config);
        Disp::Ran(used, which)
    } else {
        mainSkill.skillData.get().set(n!("triggered"), Val::Nil);
        if used.is_empty() {
            Disp::NoConfig
        } else {
            Disp::Ran(used, "arm-nil")
        }
    }
}

// ---- L4 -------------------------------------------------------------------------------------------

/// Every `triggers:*` and `perform:out` hit of the build (every env): the shared probe cache's
/// entry of that selection on the unpatched-stages copy, probed in a fresh `pob_oracle probe`
/// process when absent (`testkit::probe_selection`, `runner::SelectionCache`). CK1 (CCR-0146
/// §4): the entry is content-keyed (the patched source's sha, which covers the patcher and the
/// dump/probe Lua; the build's BLAKE3; the selection and dump cap; the probe's Rust code), so a
/// harness, dump-format or PoB change probes again. The earlier `target/tmp/tra-probe/<stem>/`
/// directory was reused whenever it held a `hits.json`, whatever made it. TR-A and TR-B probe
/// the same selection, so they share the entry. Hold the result while reading the dumps.
fn probe_dumps(xml: &Path) -> Result<pob_oracle::runner::ProbeDumps, String> {
    let opts = pob_oracle::runner::ProbeOptions {
        select: vec!["triggers:*".to_owned(), "perform:out".to_owned()],
        // the `pob_oracle probe` default the earlier private run used
        max_dumps: 200,
        provenance: false,
    };
    testkit::probe_selection(
        Path::new(env!("CARGO_BIN_EXE_pob_oracle")),
        xml,
        None,
        &opts,
    )
}

/// A file of the probe run whose dumps are `state` (`hits.json`, a `hits.json` entry's
/// `state/<hit>.json`): `<rel>.zst` in a cache entry, `<rel>` in an uncached run
/// (`POB_QUERY_CACHE=off`).
fn run_file(state: &Path, rel: &str) -> PathBuf {
    let dir = state.parent().unwrap_or(state);
    let z = dir.join(format!("{rel}.zst"));
    if z.is_file() {
        z
    } else {
        dir.join(rel)
    }
}

/// `GlobalCache.cachedData` (a snapshot of the entry handles).
fn cache_snapshot() -> [indexmap::IndexMap<Name, Rc<CachedData>>; 3] {
    pob_calc::global_cache::GlobalCache.with(|g| g.borrow().cachedData.clone())
}

const MODES: [Mode; 3] = [Mode::MAIN, Mode::CALCS, Mode::CALCULATOR];

struct HitResult {
    disp: Disp,
    mismatches: Vec<String>,
    error: Option<String>,
    stubs: Vec<String>,
    /// Mismatches attributed to `buildActiveSkill`'s build-model side effects (see `run_hit`).
    tolerated: usize,
}

/// The foreign references of a dump's cache entries: (mode index, uuid, `Env`'s env id,
/// `ActiveSkill`'s (env id, path)).
fn cache_refs(d: &StateDump) -> Vec<(usize, String, Option<String>, Option<(String, String)>)> {
    let mut out = Vec::new();
    let Some(cd) = d.root.pointer("/globalCache/cachedData") else {
        return out;
    };
    for (i, mode) in ["MAIN", "CALCS", "CALCULATOR"].iter().enumerate() {
        let Some(serde_json::Value::Object(ents)) = cd.get(*mode) else {
            continue;
        };
        for (uuid, e) in ents {
            let env = e
                .pointer("/Env/$env")
                .and_then(|v| v.as_str())
                .map(str::to_owned);
            let skill = e.pointer("/ActiveSkill/$foreign").and_then(|f| {
                Some((
                    f.get("env")?.as_str()?.to_owned(),
                    f.get("path")?.as_str()?.to_owned(),
                ))
            });
            out.push((i, uuid.clone(), env, skill));
        }
    }
    out
}

/// `<env>.player.activeSkillList[i]` / `<env>.player.mainSkill` of a resolved env.
fn resolve_skill(env: &EnvRef, path: &str) -> Option<ActiveSkillRef> {
    if path == "player.mainSkill" {
        return env.player.mainSkill.get();
    }
    let i: usize = path
        .strip_prefix("player.activeSkillList[")?
        .strip_suffix(']')?
        .parse()
        .ok()?;
    env.player
        .activeSkillList
        .get()
        .with(|l| l.get(i.checked_sub(1)?).cloned())
}

/// The socket groups of the build XML's active skill set, in order: (slot, gem skill ids).
fn xml_groups(xml: &str) -> Vec<(Option<String>, Vec<String>)> {
    let attr = |tag: &str, k: &str| -> Option<String> {
        let pat = format!(" {k}=\"");
        let i = tag.find(&pat)? + pat.len();
        let j = tag[i..].find('"')? + i;
        Some(tag[i..j].replace("&apos;", "'").replace("&amp;", "&"))
    };
    let skills = xml.split("<Skills ").nth(1).unwrap_or("");
    let head = skills.split('>').next().unwrap_or("");
    let active = attr(&format!(" {head}"), "activeSkillSet");
    let set = match active {
        Some(id) => skills
            .split("<SkillSet ")
            .skip(1)
            .find(|s| {
                attr(&format!(" {}", s.split('>').next().unwrap_or("")), "id").as_deref()
                    == Some(id.as_str())
            })
            .unwrap_or(skills),
        None => skills,
    };
    let set = set.split("</SkillSet>").next().unwrap_or(set);
    let mut out = Vec::new();
    for grp in set.split("<Skill ").skip(1) {
        let tag = format!(" {}", grp.split('>').next().unwrap_or(""));
        let body = grp.split("</Skill>").next().unwrap_or("");
        let gems = body
            .split("<Gem ")
            .skip(1)
            .filter_map(|g| {
                attr(
                    &format!(" {}", g.split('>').next().unwrap_or("")),
                    "skillId",
                )
            })
            .collect();
        out.push((attr(&tag, "slot"), gems));
    }
    out
}

/// `env.build.skillsTab.socketGroupList`: a dump writes the build as an `$object` marker and the
/// build loader (BM-A) is not ported, so `cacheSkillUUID`'s group index (Common.lua:913-918) would
/// not find the injected groups. Bind them, in the XML's order, matched by slot and gem ids.
fn bind_socket_groups(build: &BuildRef, env: &EnvRef, groups: &[(Option<String>, Vec<String>)]) {
    let mut seen: Vec<SocketGroupRef> = Vec::new();
    let mut actors = vec![env.player.clone()];
    if let Some(m) = env.minion.get() {
        actors.push(m);
    }
    let mut skills: Vec<ActiveSkillRef> = Vec::new();
    for a in &actors {
        skills.extend(a.activeSkillList.get().with(|l| l.clone()));
        skills.extend(a.mainSkill.get());
    }
    skills.extend(env.auxSkillList.get().with(|l| l.clone()));
    for s in skills {
        if let Some(g) = s.socketGroup.get() {
            if !seen.iter().any(|x| Rc::ptr_eq(x, &g)) {
                seen.push(g);
            }
        }
    }
    let mut used = vec![false; seen.len()];
    let list: Vec<SocketGroupRef> = groups
        .iter()
        .map(|(slot, gems)| {
            // same slot and gem count; the most equal gem ids wins (an old XML's legacy ids are
            // renamed by the loader, so an exact match is not required)
            let hit = seen
                .iter()
                .enumerate()
                .filter(|(i, g)| {
                    !used[*i]
                        && g.slot.get().map(|n| n.to_string()) == *slot
                        && g.gemList.get().with(|l| l.len()) == gems.len()
                })
                .map(|(i, g)| {
                    let ids: Vec<String> = g.gemList.get().with(|l| {
                        l.iter()
                            .map(|x| x.skillId.get().map(|n| n.to_string()).unwrap_or_default())
                            .collect()
                    });
                    (
                        ids.iter().zip(gems).filter(|(a, b)| a == b).count(),
                        std::cmp::Reverse(i),
                    )
                })
                .max()
                .map(|(_, std::cmp::Reverse(i))| i);
            match hit {
                Some(i) => {
                    used[i] = true;
                    seen[i].clone()
                }
                None => Rc::new(pob_calc::model::SocketGroup::default()),
            }
        })
        .collect();
    build
        .skillsTab
        .socketGroupList
        .set(pob_lua::Shared::new(list));
}

/// Run one `triggers:in#n` -> `:out#n` hit. The cache entries' `Env` / `ActiveSkill` are other
/// envs' objects, dumped as markers (`$env`, `$foreign`); they are resolved from those envs'
/// `perform:out` dumps (`env_dumps`; a `buildActiveSkill` env performs once, and the cache entry
/// is written after it), so `GlobalCache...Env.player.output.X` reads PoB's values.
fn run_hit(
    build: &BuildRef,
    din: &StateDump,
    dout: &StateDump,
    stem: &str,
    keys: &[String],
    env_dumps: &BTreeMap<String, PathBuf>,
    groups: &[(Option<String>, Vec<String>)],
) -> HitResult {
    let fail = |e: String| HitResult {
        disp: Disp::Skipped,
        mismatches: Vec::new(),
        error: Some(e),
        stubs: Vec::new(),
        tolerated: 0,
    };
    // the foreign envs the cache entries point to (injected first: every inject resets the
    // probe registry, which must end up holding `din`'s graph)
    let refs_in = cache_refs(din);
    let refs_out = cache_refs(dout);
    let mut foreign: BTreeMap<String, Option<EnvRef>> = BTreeMap::new();
    for (_, _, e, s) in refs_in.iter().chain(&refs_out) {
        for id in e.iter().chain(s.iter().map(|(id, _)| id)) {
            if foreign.contains_key(id) {
                continue;
            }
            let env = env_dumps
                .get(id)
                .and_then(|p| StateDump::load(p).ok())
                .and_then(|d| pob_oracle::inject::inject(&d, build).ok())
                .and_then(|i| i.env);
            foreign.insert(id.clone(), env);
        }
    }
    // the entries `triggers` added (its buildActiveSkill calls): `:out`'s cache minus `:in`'s
    let out_cache = match pob_oracle::inject::inject(dout, build) {
        Ok(_) => cache_snapshot(),
        Err(e) => return fail(format!("inject {}: {e}", dout.hit)),
    };
    let inj = match pob_oracle::inject::inject(din, build) {
        Ok(i) => i,
        Err(e) => return fail(format!("inject {}: {e}", din.hit)),
    };
    // whether PoB's `triggers` called `calcs.buildActiveSkill` (an entry appeared)
    let mut built = false;
    for (i, mode) in MODES.iter().enumerate() {
        for (uuid, e) in &out_cache[i] {
            if cachedData(*mode, *uuid).is_none() {
                built = true;
                pob_calc::global_cache::set_cachedData(*mode, *uuid, Some(e.clone()));
            }
        }
    }
    let mut unresolved = Vec::new();
    for (i, uuid, envId, skillRef) in refs_in.iter().chain(&refs_out) {
        let mode = MODES[*i];
        let uuid = Name::from(uuid.as_str());
        let Some(e) = cachedData(mode, uuid) else {
            continue;
        };
        let renv = envId.as_ref().map(|id| foreign.get(id).cloned().flatten());
        let rskill = skillRef.as_ref().map(|(id, path)| {
            foreign
                .get(id)
                .cloned()
                .flatten()
                .and_then(|env| resolve_skill(&env, path))
        });
        if matches!(renv, Some(None)) || matches!(rskill, Some(None)) {
            unresolved.push(uuid.to_string());
        }
        pob_calc::global_cache::set_cachedData(
            mode,
            uuid,
            Some(Rc::new(CachedData {
                Name: e.Name,
                Speed: e.Speed.clone(),
                HitSpeed: e.HitSpeed.clone(),
                ManaCost: e.ManaCost.clone(),
                LifeCost: e.LifeCost.clone(),
                ESCost: e.ESCost.clone(),
                RageCost: e.RageCost.clone(),
                HitChance: e.HitChance.clone(),
                AccuracyHitChance: e.AccuracyHitChance.clone(),
                PreEffectiveCritChance: e.PreEffectiveCritChance.clone(),
                CritChance: e.CritChance.clone(),
                TotalDPS: e.TotalDPS.clone(),
                ActiveSkill: rskill.flatten().unwrap_or_else(|| e.ActiveSkill.clone()),
                Env: renv.flatten().unwrap_or_else(|| e.Env.clone()),
            })),
        );
    }
    if !unresolved.is_empty() && std::env::var_os("TRA_DEBUG").is_some() {
        eprintln!("{}: unresolved cache entries {unresolved:?}", din.hit);
    }
    let Some(env) = inj.env.clone() else {
        return fail("no env".into());
    };
    bind_socket_groups(build, &env, groups);
    let locals: Vec<(String, Val)> = inj.locals.into_iter().collect();
    let actor = locals
        .iter()
        .find(|(k, _)| k == "actor")
        .and_then(|(_, v)| v.obj::<pob_calc::actor::Actor>());
    if std::env::var_os("TRA_DEBUG").is_some() {
        eprintln!(
            "{} actor==player {:?} player.mainSkill {:?}",
            din.hit,
            actor.as_ref().map(|a| Rc::ptr_eq(a, &env.player)),
            env.player.mainSkill.get().map(|s| ge_name(&s))
        );
        let uuids: Vec<String> = env
            .player
            .activeSkillList
            .get()
            .with(|l| l.clone())
            .iter()
            .map(|s| cacheSkillUUID(s, &env).to_string())
            .collect();
        let cached: Vec<Vec<String>> = cache_snapshot()
            .iter()
            .map(|m| m.keys().map(|k| k.to_string()).collect())
            .collect();
        eprintln!("  mode {:?} skills {uuids:?} cache {cached:?}", env.mode);
    }
    pob_calc::stub::stub_reset();
    // CA ported `calcs.buildActiveSkill`; the injected cache entries above stand in for its
    // nested calc (module doc), so the call is replayed as a no-op (it would run `initEnv` on
    // the placeholder build)
    pob_calc::modules::calcs::replay_hook::set(Some(Box::new(|_| true)));
    let run = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        scaffold_triggers(&env, actor.as_ref(), keys)
    }));
    pob_calc::modules::calcs::replay_hook::set(None);
    let stubs: Vec<String> = pob_calc::stub::stub_report()
        .into_iter()
        .map(|(s, n)| format!("{s} x{n}"))
        .collect();
    let disp = match run {
        Ok(d) => d,
        Err(p) => {
            let msg = p
                .downcast_ref::<pob_lua::LuaError>()
                .map(|e| e.0.clone())
                .or_else(|| p.downcast_ref::<String>().cloned())
                .or_else(|| p.downcast_ref::<&str>().map(|s| (*s).to_owned()))
                .unwrap_or_else(|| "panic".to_owned());
            return HitResult {
                disp: Disp::Skipped,
                mismatches: Vec::new(),
                error: Some(msg),
                stubs,
                tolerated: 0,
            };
        }
    };
    if matches!(disp, Disp::Untested(_)) {
        return HitResult {
            disp,
            mismatches: Vec::new(),
            error: None,
            stubs,
            tolerated: 0,
        };
    }
    // TR-A writes no cache entry (only CA's buildActiveSkill does): compare the env and locals,
    // with both caches emptied
    pob_calc::global_cache::clear_all();
    let mut dout = dout.clone();
    if let Some(gc) = testkit::export_after(None, &[]).get("globalCache").cloned() {
        dout.root["globalCache"] = gc;
    }
    let mut locals = locals;
    // the function's return values (`ret = { n = 0 }`: Lua returns nothing)
    locals.push(("ret".to_owned(), Val::Table(tbl! { n = 0.0 })));
    let mut tolerated = 0;
    let mismatches = testkit::diff_against(&dout, Some(&env), &locals, stem)
        .into_iter()
        .filter(|m| {
            // `calcs.buildActiveSkill` runs `calcs.initEnv` on the shared build model, which
            // rewrites the socket groups' display lists and the gems' display/support effects
            // (CalcSetup.lua 1451-1975, CS3) to the nested env's objects: CA's side effect,
            // which the injected cache entries stand in for, not TR-A's
            let ca = built
                && [
                    ".socketGroup.displaySkillList[",
                    ".socketGroup.displaySkillListCalcs[",
                    ".sourceGem.displayEffect",
                    ".sourceGem.supportEffect",
                    ".srcInstance.displayEffect",
                    ".srcInstance.supportEffect",
                    ".socketGroup.explodeSources",
                ]
                .iter()
                .any(|p| m.path.contains(p));
            // the same rewrite seen from a skill's support/effect list: PoB's effect is no
            // longer also the gem's display effect, so the identity graph names it elsewhere
            let is_ref =
                |v: &Option<serde_json::Value>| v.as_ref().is_some_and(|v| v.get("$ref").is_some());
            let ca = ca
                || (built
                    && (m.path.contains(".effectList[") || m.path.contains(".supportList["))
                    && (is_ref(&m.pob) || is_ref(&m.ours))
                    && format!("{:?}{:?}", m.pob, m.ours).contains("Effect"));
            tolerated += usize::from(ca);
            !ca
        })
        .map(|m| format!("{} {:?}: pob={:?} ours={:?}", m.path, m.kind, m.pob, m.ours))
        .collect();
    HitResult {
        disp,
        mismatches,
        error: None,
        stubs,
        tolerated,
    }
}

fn builds() -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = std::fs::read_dir(corpus_dir())
        .map(|r| {
            r.filter_map(Result::ok)
                .map(|e| e.path())
                .filter(|p| p.extension().is_some_and(|x| x == "xml"))
                .collect()
        })
        .unwrap_or_default();
    // the .parity corpus builds whose outputs carry a trigger rate
    if let Some(parity) = find_parity_dir() {
        for s in [
            "allflame_exp_000",
            "allflame_exp_033",
            "upstream_Dual_Wield_Cospris_CoC",
        ] {
            let p = parity.join("builds").join(format!("{s}.xml"));
            if p.is_file() {
                v.push(p);
            }
        }
    }
    v.sort();
    if let Ok(list) = std::env::var("TRA_BUILDS") {
        let want: Vec<&str> = list.split(',').map(str::trim).collect();
        v.retain(|p| want.contains(&stem(p)));
    }
    v
}

#[test]
fn tra_l4_triggers() {
    if !testkit::init_default_data() {
        return skip("no data dump (data/dump)");
    }
    let Some(src) = find_pob_src() else {
        return skip("no PoB checkout");
    };
    let keys = config_keys(&src);
    assert_eq!(keys.len(), 82, "configTable keys");
    let builds = builds();
    if builds.is_empty() {
        return skip("no corpus/TR-A builds");
    }
    if find_parity_dir().is_none() {
        return skip("no .parity directory (the probe cache)");
    }
    let verbose = std::env::var_os("TRA_VERBOSE").is_some();
    let mut tally: BTreeMap<String, u64> = BTreeMap::new();
    let mut handlers: BTreeMap<&'static str, u64> = BTreeMap::new();
    let mut arms: BTreeMap<String, u64> = BTreeMap::new();
    let mut untested: BTreeMap<String, u64> = BTreeMap::new();
    let mut bad: Vec<String> = Vec::new();
    let (mut compared, mut passed, mut tolerated) = (0u64, 0u64, 0u64);
    for xml in &builds {
        let stem = stem(xml).to_owned();
        let dumps = match probe_dumps(xml) {
            Ok(d) => d,
            Err(e) => {
                bad.push(format!("{stem}: {e}"));
                continue;
            }
        };
        let Ok(hits) = HitsIndex::load(&run_file(&dumps, "hits.json")) else {
            bad.push(format!("{stem}: unreadable hits.json"));
            continue;
        };
        let file_of = |hit: &str| {
            hits.dumps
                .iter()
                .find(|d| d.hit == hit)
                .map(|d| run_file(&dumps, &d.file))
        };
        let build = testkit::load_build(xml).unwrap_or_else(testkit::empty_build);
        let groups = xml_groups(&std::fs::read_to_string(xml).unwrap_or_default());
        // env id -> its first `perform:out` dump
        let mut env_dumps: BTreeMap<String, PathBuf> = BTreeMap::new();
        for d in &hits.dumps {
            if d.hit.starts_with("perform:out#") {
                if let Some(e) = &d.env {
                    env_dumps
                        .entry(e.clone())
                        .or_insert_with(|| run_file(&dumps, &d.file));
                }
            }
        }
        let ins: Vec<String> = hits
            .dumps
            .iter()
            .filter(|d| d.hit.starts_with("triggers:in#"))
            .map(|d| d.hit.clone())
            .collect();
        for hin in ins {
            let hout = hin.replace(":in#", ":out#");
            let (Some(pin), Some(pout)) = (file_of(&hin), file_of(&hout)) else {
                *tally.entry("no :out dump".into()).or_default() += 1;
                continue;
            };
            let (Ok(din), Ok(dout)) = (StateDump::load(&pin), StateDump::load(&pout)) else {
                bad.push(format!("{stem} {hin}: unreadable dump"));
                continue;
            };
            let r = run_hit(&build, &din, &dout, &stem, &keys, &env_dumps, &groups);
            drop((din, dout));
            let main = hits.main_env.as_deref()
                == hits
                    .dumps
                    .iter()
                    .find(|d| d.hit == hin)
                    .and_then(|d| d.env.as_deref());
            let label = format!("{stem} {hin}{}", if main { " (main env)" } else { "" });
            if let Some(e) = r.error {
                bad.push(format!(
                    "{label}: error {e} [stubs: {}]",
                    r.stubs.join(", ")
                ));
                compared += 1;
                continue;
            }
            match &r.disp {
                Disp::Untested(k) => {
                    *untested.entry(k.clone()).or_default() += 1;
                    *tally.entry("untested (TR-B arm)".into()).or_default() += 1;
                    continue;
                }
                Disp::Skipped => {
                    *tally
                        .entry("skipped (disabled/limited)".into())
                        .or_default() += 1
                }
                Disp::NoConfig => *tally.entry("no config".into()).or_default() += 1,
                Disp::Ran(k, h) => {
                    *handlers.entry(h).or_default() += 1;
                    *arms.entry(k.clone()).or_default() += 1;
                }
            }
            compared += 1;
            tolerated += r.tolerated as u64;
            if r.mismatches.is_empty() {
                passed += 1;
            } else {
                let n = r.mismatches.len();
                let shown: Vec<&String> = r
                    .mismatches
                    .iter()
                    .take(if verbose { usize::MAX } else { 8 })
                    .collect();
                bad.push(format!(
                    "{label} {:?}: {n} mismatches [stubs: {}]\n    {}",
                    r.disp,
                    r.stubs.join(", "),
                    shown
                        .iter()
                        .map(|s| s.as_str())
                        .collect::<Vec<_>>()
                        .join("\n    ")
                ));
            }
        }
    }
    eprintln!(
        "TR-A L4: {} builds, {compared} hits compared, {passed} passed ({tolerated} build-model mismatches from buildActiveSkill side effects tolerated)",
        builds.len()
    );
    eprintln!("  dispositions: {tally:?}");
    eprintln!("  handlers: {handlers:?}");
    eprintln!("  arms run: {arms:?}");
    eprintln!("  untested (arm not in the scaffold): {untested:?}");
    for b in &bad {
        eprintln!("FAIL {b}");
    }
    assert!(bad.is_empty(), "{} failing hits", bad.len());
    for h in ["default", "CWC", "Focus"] {
        assert!(
            handlers.get(h).copied().unwrap_or(0) > 0,
            "no compared hit through the {h} handler"
        );
    }
}
